// Boot, title screen, save/load, evolution scenes, main loop.
window.Game = (() => {
  const canvas = document.getElementById('screen');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const wait = (ms) => new Promise(r => setTimeout(r, ms));

  // Integer-ish upscale to fit the window.
  function fit() {
    const scale = Math.max(1, Math.min(
      Math.floor(innerWidth * 0.95 / 240),
      Math.floor(innerHeight * 0.88 / 160)));
    canvas.style.width = 240 * scale + 'px';
    canvas.style.height = 160 * scale + 'px';
  }
  addEventListener('resize', fit); fit();

  const SAVE_KEY = 'firered-fan-save';

  function freshSave() {
    return {
      party: [], box: [], bag: {},
      money: 3000,
      flags: {}, seen: {}, caught: {}, defeated: {},
      respawn: { map: 'player-house', x: 4, y: 5 },
      pendingEvos: [],
    };
  }

  const Game = {
    state: 'title',
    save: freshSave(),
    persist() {
      const s = { ...this.save, pendingEvos: undefined };
      const pos = { map: Overworld.player.map, x: Overworld.player.x, y: Overworld.player.y, dir: Overworld.player.dir };
      localStorage.setItem(SAVE_KEY, JSON.stringify({ save: s, pos }));
    },
    load() {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return false;
      try {
        const data = JSON.parse(raw);
        this.save = { ...freshSave(), ...data.save, pendingEvos: [] };
        Overworld.setPos(data.pos.map, data.pos.x, data.pos.y, data.pos.dir);
        return true;
      } catch { return false; }
    },

    async evolveScene(mon, toId) {
      const fromName = Pkmn.dname(mon);
      const state = { id: mon.id, flash: 0 };
      const widget = {
        kind: 'evo', done: new Promise(() => {}),
        update() {},
        draw(c) {
          const g = c.createLinearGradient(0, 0, 0, 160);
          g.addColorStop(0, '#283060'); g.addColorStop(1, '#6048a0');
          c.fillStyle = g; c.fillRect(0, 0, 240, 160);
          const img = Gfx.monSprite(state.id, 'front');
          c.save();
          if (state.flash) { c.filter = 'brightness(3)'; }
          if (img.complete) c.drawImage(img, 72, 8, 96, 96);
          c.restore();
        },
      };
      UI._push(widget);
      await UI.message(`What?\n${fromName} is evolving!`);
      Audio2.evolve();
      for (let i = 0; i < 14; i++) {
        state.id = i % 2 ? toId : mon.id;
        state.flash = i % 2;
        await wait(Math.max(60, 320 - i * 22));
      }
      state.id = toId; state.flash = 0;
      Pkmn.evolve(mon, toId);
      this.save.caught[toId] = true; this.save.seen[toId] = true;
      Audio2.catchSuccess();
      await UI.message(`Congratulations! Your\n${fromName} evolved into\n${Pkmn.dname(mon)}!`);
      for (const mv of Pkmn.movesLearnedAt(mon, mon.level)) await Battle.learnMove(mon, mv);
      UI._pop(widget);
    },

    async runEvolutions() {
      const queue = this.save.pendingEvos;
      while (queue.length) {
        const { mon, to } = queue.shift();
        const stillValid = POKEDEX[mon.id].evolvesTo.some(e => e.to === to);
        const owned = this.save.party.includes(mon) || this.save.box.includes(mon);
        if (stillValid && owned) await this.evolveScene(mon, to);
      }
    },
  };

  // ---- Title screen ----------------------------------------------------------
  let titleIdx = 0;
  let titleMon = 6; // Charizard
  function drawTitle() {
    const g = ctx.createLinearGradient(0, 0, 0, 160);
    g.addColorStop(0, '#c83820'); g.addColorStop(1, '#702010');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 240, 160);
    ctx.fillStyle = 'rgba(255,200,80,.18)';
    ctx.beginPath(); ctx.arc(120, 70, 60, 0, 7); ctx.fill();
    const img = Gfx.monSprite(titleMon, 'front');
    if (img.complete) ctx.drawImage(img, 88, 26, 64, 64);
    Gfx.text(ctx, 'POKéMON', 99, 8, '#f8d020');
    Gfx.text(ctx, 'FIRERED', 99, 18, '#f8f8f8');
    Gfx.text(ctx, 'FAN REMAKE', 90, 92, '#f8b838');
    const hasSave = !!localStorage.getItem(SAVE_KEY);
    const opts = hasSave ? ['CONTINUE', 'NEW GAME'] : ['NEW GAME'];
    opts.forEach((o, i) => {
      Gfx.text(ctx, o, 96, 112 + i * 12, i === titleIdx ? '#f8f8f8' : '#c89888');
      if (i === titleIdx) Gfx.text(ctx, '>', 86, 112 + i * 12, '#f8d020');
    });
    Gfx.text(ctx, 'ALL 151 POKéMON INSIDE', 54, 148, '#e8a888');
  }

  function titleUpdate() {
    const hasSave = !!localStorage.getItem(SAVE_KEY);
    const n = hasSave ? 2 : 1;
    if (Input.press('up') || Input.press('down')) { titleIdx = (titleIdx + 1) % n; Audio2.beep(); }
    if ((performance.now() / 4000 | 0) % 2) titleMon = [6, 9, 3, 25, 150][(performance.now() / 4000 | 0) % 5];
    if (Input.press('a') || Input.press('menu')) {
      Audio2.select();
      const newGame = !hasSave || titleIdx === (hasSave ? 1 : 0);
      if (newGame) {
        localStorage.removeItem(SAVE_KEY);
        Game.save = freshSave();
        Overworld.setPos('player-house', 4, 5, 'down');
        Game.state = 'play';
        Overworld.script(async () => {
          await UI.message('Welcome to the world of\nPOKéMON!');
          await UI.message('Your very own POKéMON\nlegend is about to unfold!');
          await UI.message('(Visit PROF. OAK in the lab\nsouth of your house to get\nyour first POKéMON!)');
        });
      } else {
        Game.load();
        Game.state = 'play';
      }
    }
  }

  // Block leaving Pallet with no Pokémon.
  const _origUpdate = Overworld.update;

  // ---- Main loop ---------------------------------------------------------------
  Gfx.preloadAll();
  let last = 0;
  function loop(t) {
    requestAnimationFrame(loop);
    if (t - last < 14) return; // ~60fps cap
    last = t;
    if (Game.state === 'title') {
      titleUpdate();
      drawTitle();
      UI.update(); UI.draw(ctx);
      Input.endFrame();
      return;
    }
    UI.update();
    Overworld.update();
    if (Battle.active()) Battle.draw(ctx);
    else Overworld.draw(ctx);
    UI.draw(ctx);
    Input.endFrame();
  }
  requestAnimationFrame(loop);

  return Game;
})();
